with flattened as (select id, service, log_ts, level, latency_ms, attr_key, attr_value from app_logs lateral view explode(context) e as attr_key, attr_value), enriched as (select *, cume_dist() over w_grp as latency_ms_cume_dist, avg(latency_ms) over (order by log_ts, id, attr_key rows between 2 preceding and current row) as latency_ms_avg_2, dense_rank() over (partition by service order by latency_ms nulls first) as latency_ms_dense_rank from flattened window w_grp as (partition by level, attr_key order by latency_ms desc)), gaps as (select *, case when lag(log_ts) over (partition by attr_key order by log_ts, id, attr_key) is null or log_ts > lag(log_ts) over (partition by attr_key order by log_ts, id, attr_key) + interval 45 minutes then 1 else 0 end as is_new_session from enriched), sessions_app_logs as (select *, sum(is_new_session) over (partition by attr_key order by log_ts, id, attr_key rows between unbounded preceding and current row) as session_id from gaps), enriched_app_logs as (select *, lag(latency_ms, 1) over (partition by level order by latency_ms_dense_rank, id, attr_key) as prev_latency_ms, last_value(attr_key, true) over w_running as last_known_attr_key from sessions_app_logs window w_running as (partition by attr_key, level order by session_id, id, attr_key rows between unbounded preceding and current row)), deduped as (select *, rank() over (partition by service order by latency_ms_dense_rank) as latest_rank from enriched_app_logs qualify latest_rank = 1) select level, min(log_ts) as started_at, count(*) filter (where service = 'billing') as billing_rows, grouping_id() as grouping_id from deduped group by rollup (level)
